CREATE function [dbo].[uspGetRate] ( @StoreId int,@ItemId  int,@Date datetime,@ByDate bit) returns nvarchar(50) as Begin Declare @Amount decimal(18,2); set @Amount =0; Declare @Qty decimal(18,2); set @Qty =0; Declare @Rate decimal(18,2) ; set @Rate =0; if @ByDate = 0 begin select @Rate = (select distinct rate  from Warehouse_store where  id=( select max( id) from Warehouse_store where itemid = @ItemId and [type] = 'in' ) and itemid = @ItemId and sid=@StoreId and [type] = 'in' ) End else if @ByDate = 1 begin  select @Rate=(select distinct rate   from Warehouse_store where  id =( select max( id) from Warehouse_store where itemid = @ItemId and [type] = 'in' and date <= @Date  ) and itemid = @ItemId and sid=@StoreId and [type] = 'in' ) End return @Rate End